macro.command:
// 奥术回想 - 物品宏形式
// 点击角色卡内的专属能力或物品时使用
// 兼容 FoundryVTT DND5e

if (!actor) return ui.notifications.warn("没有找到角色！");
if (!item) return ui.notifications.warn("没有找到奥术回想ArcaneRecovery物品！");

// 检查使用次数
const uses = item.system.uses?.value ?? 0;
const usesMax = item.system.uses?.max ?? 1;
if (uses < 1) {
  return ui.notifications.warn("奥术回想已没有剩余使用次数！");
}

// 先消耗一次
await item.update({"system.uses.value": uses - 1});

// 以下为奥术回想的主要功能
const wizardLevel = actor.items.find(i => i.type==="class" && i.name==="法师wizard")?.system.levels;
if (!wizardLevel) return ui.notifications.warn("找不到你的法师等级！");

const maxPoints = Math.ceil(wizardLevel / 2);
const slotLevels = [1,2,3,4,5];

let maxRecoverable = {};
slotLevels.forEach(lvl => {
  const total = getProperty(actor.system, `spells.spell${lvl}.max`) ?? 0;
  const used = total - (getProperty(actor.system, `spells.spell${lvl}.value`) ?? 0);
  maxRecoverable[lvl] = Math.max(0, used);
});

let content = `<form><div>你最多可恢复一共 <b>${maxPoints}</b> 环法术位（注意奥术回想所恢复的单个环位最高不能超过5环）：</div>`;
slotLevels.forEach(lvl => {
  content += `
    <div class="form-group">
      <label>${lvl}环（已消耗: ${maxRecoverable[lvl]}）:</label>
      <input type="number" min="0" max="${maxRecoverable[lvl]}" value="0" id="arcane-lvl${lvl}">
    </div>
  `;
});
content += `</form>`;

new Dialog({
  title: "奥术回想 - 恢复法术位",
  content,
  buttons: {
    confirm: {
      label: "恢复",
      callback: async (html) => {
        let totalSpent = 0;
        let restoreData = {};
slotLevels.forEach(lvl => {
          let n = Number(html.find(`#arcane-lvl${lvl}`).val()) || 0;
          n = Math.min(n, maxRecoverable[lvl]);
          totalSpent += lvl * n;
          restoreData[lvl] = n;
});
        if (totalSpent === 0) {
          return ui.notifications.warn("你没有选择恢复任何法术位。");
}
        if (totalSpent > maxPoints) {
          return ui.notifications.warn(`你选择的法术位总环数为${totalSpent}，已超过最大可恢复点数${maxPoints}！`);
}

        // 更新法术位
        let updates = {};
slotLevels.forEach(lvl => {
          if (restoreData[lvl] > 0) {
            const path = `system.spells.spell${lvl}.value`;
            const cur = getProperty(actor, path) ?? 0;
            updates[path] = Math.min(
              cur + restoreData[lvl],
              getProperty(actor.system, `spells.spell${lvl}.max`) ?? 0
            );
}
});

        await actor.update(updates);

        // 聊天提示
        let txt = `${actor.name} 用奥术回想恢复了：`;
        txt += slotLevels.filter(lvl => restoreData[lvl]>0).map(lvl=>`${restoreData[lvl]}个${lvl}环`).join("，");
        txt += `（共消耗点数${totalSpent}，最大可用${maxPoints}）`;
        ChatMessage.create({
          speaker: ChatMessage.getSpeaker({actor: actor}),
          content: txt
});
}
    },
    cancel: { label: "取消" }
}
}).render(true);
